def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1  # Only the number 1 itself is a n-digit number that starts or ends with 1
    else:
        # For n-digit numbers, the first digit can be any digit from 1 to 9, and the last digit can be any digit from 0 to 9
        # So, the total count is 10^(n-1)
        return 10**(n-1)

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1
    else:
        # For n-digit numbers, the first and last digits can be 1 or 9.
        # The middle digits can be any digit from 0 to 9.
        # So, the count is 2 * 10^(n-2).
        return 2 * (10 ** (n - 2))

