def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = "aeiouAEIOU"
    encoded_message = []

    for char in message:
        if char.isalpha():
            if char in vowels:
                # Replace vowel with the letter that appears 2 places ahead in the alphabet
                if char == 'a':
                    encoded_message.append('e')
                elif char == 'e':
                    encoded_message.append('i')
                elif char == 'i':
                    encoded_message.append('o')
                elif char == 'o':
                    encoded_message.append('u')
                elif char == 'u':
                    encoded_message.append('a')
            else:
                # Swap case
                encoded_message.append(char.swapcase())
        else:
            # Non-alphabetic characters are added to the result without change
            encoded_message.append(char)

    return ''.join(encoded_message)

